begin;
create extension if not exists pgtap with schema extensions;
set search_path to public,extensions;
select no_plan();
select ok((select relrowsecurity from pg_class where oid='private.staff_onboarding'::regclass),'Onboarding com RLS');
select ok((select relrowsecurity from pg_class where oid='private.staff_permission_overrides'::regclass),'Exceções com RLS');
select ok(not has_table_privilege('authenticated','private.staff_permission_overrides','SELECT'),'Exceções privadas');
select ok(not has_table_privilege('service_role','private.staff_onboarding','INSERT'),'Serviço sem escrita direta');
select ok(not has_function_privilege('authenticated','public.provision_invited_staff(uuid,uuid,text,uuid,boolean,boolean,jsonb)','EXECUTE'),'Provisionamento exclusivo do servidor');
select ok(not has_function_privilege('authenticated','public.complete_staff_onboarding(uuid)','EXECUTE'),'Conclusão exclusiva do servidor');
select ok(not has_function_privilege('authenticated','public.prepare_staff_invitation(uuid,text,text)','EXECUTE'),'Ticket exclusivo do servidor');
select ok(has_function_privilege('supabase_auth_admin','public.guard_candidate_signup(jsonb)','EXECUTE'),'Hook de Auth preservado');
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,invited_at) values
 ('00000000-0000-4000-8000-000000000151','principal-invite@example.test',now(),'{"provider":"email"}',null),
 ('00000000-0000-4000-8000-000000000152','recipient-invite@example.test',null,'{"provider":"email"}',now()),
 ('00000000-0000-4000-8000-000000000153','other-invite@example.test',now(),'{"provider":"email"}',null);
insert into public.staff(user_id,display_name,mfa_enabled,password_login_enabled) values
 ('00000000-0000-4000-8000-000000000151','Principal fictício',true,true),
 ('00000000-0000-4000-8000-000000000153','Outro administrador',false,true);
insert into public.staff_roles(user_id,role_id) select u.id,r.id from auth.users u cross join public.roles r
 where u.id in ('00000000-0000-4000-8000-000000000151','00000000-0000-4000-8000-000000000153') and r.name='Superadministrador';
update private.primary_administrator set user_id='00000000-0000-4000-8000-000000000151';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000153","role":"authenticated","aal":"aal2","app_metadata":{"provider":"email"}}',true);
select throws_ok($$select public.staff_administration_details()$$,'42501','permission_denied','Outro Superadministrador não lista detalhes');
select ok(not public.has_permission('users.manage'),'Gestão de usuários não delegável');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000151","role":"authenticated","aal":"aal1","app_metadata":{"provider":"email"}}',true);
select throws_ok($$select public.reserve_staff_invitation()$$,'42501','permission_denied','Principal precisa de AAL2 para convidar');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000151","role":"authenticated","aal":"aal2","app_metadata":{"provider":"email"}}',true);
select ok(public.reserve_staff_invitation(),'Principal reserva convite');
select throws_ok($$select public.update_staff_administration('00000000-0000-4000-8000-000000000151','Principal', (select id from public.roles where name='Superadministrador'),true,false,'{}')$$,'P0001','invalid_staff_target','Principal protegido');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.prepare_staff_invitation('00000000-0000-4000-8000-000000000151','new-invite@example.test',encode(digest(repeat('e',64),'sha256'),'hex'))$$,'Servidor prepara ticket');
select lives_ok($$select public.provision_invited_staff('00000000-0000-4000-8000-000000000151','00000000-0000-4000-8000-000000000152','Destinatário fictício',(select id from public.roles where name='Recrutador'),true,false,'{"settings.read":true,"settings.manage":false,"candidates.edit":false}')$$,'Convite com permissões individuais');
select throws_ok($$select public.complete_staff_onboarding('00000000-0000-4000-8000-000000000152')$$,'P0001','invalid_staff_target','Sem confirmação não conclui');
reset role;
select ok(public.guard_candidate_signup('{"user":{"email":"wrong@example.test","app_metadata":{"provider":"email"},"user_metadata":{"staff_invitation_ticket":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"}}}') ? 'error','Ticket não libera outro e-mail');
select is(public.guard_candidate_signup('{"user":{"email":"new-invite@example.test","app_metadata":{"provider":"email"},"user_metadata":{"staff_invitation_ticket":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"}}}'),'{}'::jsonb,'Ticket interno validado');
select ok(public.guard_candidate_signup('{"user":{"email":"new-invite@example.test","app_metadata":{"provider":"email"},"user_metadata":{"staff_invitation_ticket":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"}}}') ? 'error','Ticket de uso único');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000152","role":"authenticated","aal":"aal1","app_metadata":{"provider":"email"}}',true);
select is(public.candidate_registration_status(),'password_required','Convite exige senha antes do acesso');
select ok(not public.is_staff(),'Convite pendente não acessa gestão');
select ok(not public.portal_session_allowed(),'Convite pendente não acessa candidato');
select ok(not public.has_permission('candidates.read'),'Sem RBAC antes da conclusão');
reset role;
update auth.users set email_confirmed_at=now() where id='00000000-0000-4000-8000-000000000152';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.complete_staff_onboarding('00000000-0000-4000-8000-000000000152')$$,'P0001','invalid_staff_target','Confirmação sem senha não conclui');
reset role;
update auth.users set encrypted_password=crypt('Ficticia!123456Aa',gen_salt('bf')) where id='00000000-0000-4000-8000-000000000152';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.complete_staff_onboarding('00000000-0000-4000-8000-000000000152')$$,'Confirmação e senha concluem');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000152","role":"authenticated","aal":"aal1","app_metadata":{"provider":"email"}}',true);
select ok(public.has_permission('candidates.read'),'Leitura herdada');
select ok(public.has_permission('talents.read'),'Banco de talentos herdado');
select ok(not public.has_permission('candidates.edit'),'Edição individual bloqueada');
select ok(public.has_permission('settings.read'),'Leitura de configurações permitida');
select ok(not public.has_permission('settings.manage'),'Alteração de configurações bloqueada');
select throws_ok($$select public.manage_catalog('departments','Cadastro indevido',null,true)$$,'42501','permission_denied','RPC respeita somente leitura');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000151","role":"authenticated","aal":"aal2","app_metadata":{"provider":"email"}}',true);
select throws_ok($$select public.update_staff_administration('00000000-0000-4000-8000-000000000152','Destinatário alterado',(select id from public.roles where name='Recrutador'),true,false,'{"users.manage":true}')$$,'P0001','invalid_permissions','Permissão exclusiva não delegável');
select is((select display_name from public.staff where user_id='00000000-0000-4000-8000-000000000152'),'Destinatário fictício','Atualização inválida é atômica');
select lives_ok($$select public.update_staff_administration('00000000-0000-4000-8000-000000000152','Destinatário fictício',(select id from public.roles where name='Recrutador'),true,false,'{"candidates.read":false,"candidates.edit":true}')$$,'Administrador define exceções');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000152","role":"authenticated","aal":"aal1","app_metadata":{"provider":"email"}}',true);
select ok(not public.has_permission('candidates.edit'),'Sem visualização não pode editar');
select ok(not public.has_permission('talents.read'),'Banco de talentos depende de leitura de candidatos');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000151","role":"authenticated","aal":"aal2","app_metadata":{"provider":"email"}}',true);
select lives_ok($$select public.update_staff_administration('00000000-0000-4000-8000-000000000152','Destinatário fictício',(select id from public.roles where name='Recrutador'),false,false,'{}')$$,'Desativação pelo principal');
select lives_ok($$select public.update_staff_administration('00000000-0000-4000-8000-000000000152','Destinatário fictício',(select id from public.roles where name='Recrutador'),true,false,'{}')$$,'Reativação pelo principal');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000152","role":"authenticated","aal":"aal1","app_metadata":{"provider":"email"}}',true);
select ok(not public.is_staff(),'Sessão antiga continua revogada após reativação');
select is(public.candidate_registration_status(),'unavailable','Sessão revogada também bloqueia portal');
reset role;
insert into public.jobs(id,slug,title,city,work_model,description) values('00000000-0000-4000-8000-000000000151','scope-invite-test','Vaga fictícia','Cidade fictícia','Remoto','Descrição fictícia para escopo de permissões.');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000151","role":"authenticated","aal":"aal2","app_metadata":{"provider":"email"}}',true);
select lives_ok($$select public.update_staff_administration('00000000-0000-4000-8000-000000000153','Outro administrador',(select id from public.roles where name='Gestor da vaga'),true,false,'{"candidates.edit":true}')$$,'Exceção em perfil de vagas atribuídas');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000153","role":"authenticated","aal":"aal1","app_metadata":{"provider":"email"}}',true);
select ok(not public.has_permission('candidates.edit'),'Exceção não concede acesso global ao perfil atribuído');
select ok(not public.has_permission('candidates.edit','00000000-0000-4000-8000-000000000151'),'Sem atribuição não edita vaga');
reset role;
insert into public.job_assignments(job_id,user_id) values('00000000-0000-4000-8000-000000000151','00000000-0000-4000-8000-000000000153');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000153","role":"authenticated","aal":"aal1","app_metadata":{"provider":"email"}}',true);
select ok(public.has_permission('candidates.edit','00000000-0000-4000-8000-000000000151'),'Exceção permitida somente na vaga atribuída');
select ok(not public.has_permission('users.manage'),'Exceção não altera exclusividade do principal');
reset role;
select ok(exists(select 1 from public.audit_events where action='ONBOARDING_COMPLETE' and resource_id='00000000-0000-4000-8000-000000000152'),'Conclusão auditada');
select * from finish();
rollback;
